                source = LIVE;
            } else {
                source = null;
                try (PreparedStatement ps = c.prepareStatement("SELECT id FROM sheet_snapshot "
                        + "WHERE sheet_id = ? AND today_was <= ? AND today_now > ? ORDER BY id DESC LIMIT 1")) {

